bool DieMuxData::isDieApplicable(const Object *obj, const DamageInfo *damageInfo) const
{
	if (!(m_deathTypes & (1u << (damageInfo->in.m_deathType - 1))))
		return false;
	if (!obj->m_status.testSetAndClear(m_requiredStatus, m_exemptStatus))
		return false;
	if (m_damageThreshold >= 0.0f && m_damageThreshold > damageInfo->in.m_amount)
		return false;
	if (m_angleMin < m_angleMax)
	{
		Object *source = TheGameLogic->findObjectByID(damageInfo->in.m_sourceID);
		if (source == NULL)
			return false;
		Coord3D direction;
		obj->getPlanarDirectionTo(&direction, source);
		Real orientation = obj->getOrientation();
		Real sourceAngle = atan2(direction.y, direction.x);
		Real angle = normalizeAngle(orientation - sourceAngle);
		Real midpoint = (m_angleMax + m_angleMin) * 0.5f;
		Real halfRange = m_angleMax - midpoint;
		if (fabs(normalizeAngle(angle - midpoint)) > halfRange)
			return false;
	}
	return true;
}

